-- Email reminders require a reader's request-specific opt-in and a counsel decision.
CREATE TABLE s_request_consents(request_id TEXT NOT NULL REFERENCES s_document_requests(id),email TEXT NOT NULL,wording TEXT NOT NULL,version TEXT NOT NULL,granted_at TEXT NOT NULL,revoked_at TEXT,PRIMARY KEY(request_id,email));
CREATE TABLE s_request_reminders(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES s_document_requests(id),email TEXT NOT NULL,approved_by TEXT NOT NULL,approved_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('active','stopped','escalated')),reason TEXT NOT NULL DEFAULT '',UNIQUE(request_id,email));
CREATE TABLE s_request_reminder_sends(id TEXT PRIMARY KEY,reminder_id TEXT NOT NULL REFERENCES s_request_reminders(id),step INTEGER NOT NULL,due_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('queued','sending','sent','failed','uncertain','cancelled')),attempted_at TEXT,provider TEXT,provider_id TEXT,detail TEXT NOT NULL DEFAULT '',UNIQUE(reminder_id,step));
